T.en=T.en||{};Object.assign(T.en,{"딩동댕— 수업 시작 종이 울렸다.": "Ding-dong— the bell for class rang."});
T.vi=T.vi||{};Object.assign(T.vi,{"딩동댕— 수업 시작 종이 울렸다.": "Đinh đoong— chuông vào học vang lên."});
T.zh=T.zh||{};Object.assign(T.zh,{"딩동댕— 수업 시작 종이 울렸다.": "叮咚当——上课铃响了。"});
T.ja=T.ja||{};Object.assign(T.ja,{"딩동댕— 수업 시작 종이 울렸다.": "キンコンカン——授業開始のチャイムが鳴った。"});
T.ru=T.ru||{};Object.assign(T.ru,{"딩동댕— 수업 시작 종이 울렸다.": "Динь-дон — прозвенел звонок на урок."});
T.id=T.id||{};Object.assign(T.id,{"딩동댕— 수업 시작 종이 울렸다.": "Ding-dong— bel masuk kelas berbunyi."});
